# The park as a whole: the card that the park's other cards name as their parent (id `park_scene`).
from grass_lib import *
W_GP = X('Greenwich Park (Wikipedia)', 'https://en.wikipedia.org/wiki/Greenwich_Park')
N('park_scene', 'Greenwich Park', 'habitat', 300, [],
  "The park in this explorer: a small, simplified patch of Greenwich Park in London, with a person, a dog, oaks, a pond, a boulder, a robin, a bee, a mushroom, buttercups and a lawn, all drawn at true size under the real Sun for the chosen date and time.",
  "You start in the park. Everything standing in it is a model drawn at its real size, so the bee is 14 mm long next to a dog and a person. Click any living thing, or the ground, the pond, the Sun or the sky, to open a card about it. Scroll toward something to go inside it: through the skin and muscle of the dog or yourself, into a leaf of the oak or the grass, down through the pond water or the soil, and on down to cells and molecules. The lighting comes from the real Sun for the date and time shown on the card, so the park is lit differently in June and December.",
  "The real Greenwich Park is a Royal Park in the Royal Borough of Greenwich, London, of about 74 hectares (the infobox gives 74.5 ha, or 184 acres), which straddles the Greenwich Prime Meridian; the Royal Observatory stands on the hilltop near its centre. It is part of the Greenwich World Heritage Site and was the first of London's eight Royal Parks to be enclosed, in 1433 (Wikipedia). The park in this explorer is not a map of it: the ground is a simplified disc, and what stands on it (the pond, the oaks, the boulders, the lawn) are models placed to show the kinds of living thing and material you can meet in a British park.",
  "Every object in the park is a model built from typical measurements and says so on its own card; nothing here is a scan of a real tree, animal or pond. The oaks, the grass and the buttercups are drawn after the species named on their cards; positions and numbers are choices.",
  [('Real park, area', '≈ 74 ha (74.5 ha, 184 acres in the infobox)'), ('Real park, position', 'straddles the Greenwich Prime Meridian; Royal Observatory on the hilltop'), ('Status', 'Royal Park; part of the Greenwich World Heritage Site; first London Royal Park enclosed, 1433'), ('In this explorer', 'a simplified patch with true-size models, lit by the real Sun for the chosen date and time')],
  'C1', [R_ECO], [W_GP], parts=['human_body', 'dog', 'oak_english', 'park_bee', 'rn_acris', 'park_mushroom', 'robin', 'park_pond', 'boulder', 'grass_plant', 'grass_lawn', 'park_ground', 'park_sky', 'park_sun', 'park_cloud'], related=['park_ground', 'grass_lawn'])
